import React from 'react';
import EnhancedSurveyStats from '../components/dashboard/EnhancedSurveyStats';

function Dashboard() {
  return (
    <div className="space-y-6">
      {/* Enhanced ISP Site Survey Statistics */}
      <div className="flex justify-center">
        <div className="w-full max-w-6xl">
          <EnhancedSurveyStats />
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
